  drone_junk_dog: {"page": 344, "summary": "Scrap-built medium dog drone with an olfactory scanner 5 and a small weapon mount; its bite deals 3P at AR 6."},
  drug_alcohol: {"page": 312, "summary": "Everything from synthahol beer to hard liquor; price ranges widely by quality."},
  drug_bliss: {"page": 312, "summary": "Synthetic opiate tranquilizer prized for its escapist calm."},
  drug_cram: {"page": 312, "summary": "Cheap, popular stimulant; users take unresisted Stun damage when it wears off."},
  drug_deepweed: {"page": 312, "summary": "Awakened-kelp narcotic that pushes magically active users into astral perception, followed by a dice pool penalty afterward."},
