  drug_nitro: {"page": 312, "summary": "Dangerous stimulant blend popular with troll gangers; the crash brings unresisted Stun and a penalty on all tests."},
  drug_novacoke: {"page": 312, "summary": "Highly addictive social stimulant; afterward Charisma and Willpower drop to zero for a while."},
  drug_psyche: {"page": 312, "summary": "Designer focus drug favored by magicians and technomancers since it halves the dice penalty from sustaining spells or complex forms."},
