  toxin_pepper_punch: {"page": 312, "summary": "Capsaicin-laced self-defense spray that burns skin and eyes; often tagged with dye or RFID markers to identify those hit."},
  toxin_seven_7: {"page": 312, "summary": "Military nerve gas engineered to get past chemical protection, dealing Physical damage plus cramps and blurred vision."},
