  maglock_card_reader: {"page": 278, "summary": "Keycard or passcard access control for a maglock."},
  containment_manacles: {"page": 278, "summary": "Linked wrist and ankle restraints that limit the wearer to a shuffle and block implant weapons from extending."},
  maglock_keypad: {"page": 278, "summary": "Code-entry access control for a maglock."},
