  cellular_glove_molder: {"page": 279, "summary": "Copies a fingerprint or palm print into a wearable sleeve for fooling some biometric locks."},
  chisel_wrecking_bar: {"page": 279, "summary": "Heavy pry bar that doubles your effective Strength when forcing doors, locks, or containers."},
  miniwelder_fuel: {"page": 279, "summary": "Replacement power supply for a miniwelder."},
  monofilament_chainsaw: {"page": 279, "summary": "Motorized saw with monowire-edged teeth for cutting through barriers; not usable as a proper melee weapon."},
  sequencer: {"page": 279, "summary": "Electronic tool needed to defeat keypad maglocks; wireless operation raises its effective rating."},
